//! Golden-file serialization tests. Every folder under `fixtures/golden` is a
//! project: opening and saving it must write exactly the files in its
//! `expected/` (or, without one, its `input/` again), and a second save must
//! change nothing. `BLOCKLOOM_BLESS=1` rewrites the expected files, which is
//! how a deliberate format change shows up in review.
//!
//! The kitchen and legacy inputs are generated by the ignored
//! `regenerate_golden_inputs`; ids change every time it runs.

use blockloom_core::project::{self, Project};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/golden")
}

fn scratch(tag: &str) -> PathBuf {
    let path = std::env::temp_dir().join(format!(
        "blockloom-golden-{tag}-{}",
        uuid::Uuid::new_v4().simple()
    ));
    std::fs::create_dir_all(&path).unwrap();
    path
}

fn blessing() -> bool {
    std::env::var_os("BLOCKLOOM_BLESS").is_some_and(|v| v != "0")
}

/// Every document under `dir` by relative path, skipping `.blockloom/`
/// (revision, locks, caches), which is bookkeeping rather than the document.
fn documents(dir: &Path) -> BTreeMap<String, String> {
    fn walk(root: &Path, dir: &Path, out: &mut BTreeMap<String, String>) {
        let mut entries: Vec<_> = std::fs::read_dir(dir).unwrap().flatten().collect();
        entries.sort_by_key(|e| e.file_name());
        for entry in entries {
            let path = entry.path();
            let name = entry.file_name().to_string_lossy().into_owned();
            if name.starts_with('.') {
                continue;
            }
            if path.is_dir() {
                walk(root, &path, out);
            } else {
                let relative = path
                    .strip_prefix(root)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                out.insert(relative, std::fs::read_to_string(&path).unwrap());
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(dir, dir, &mut out);
    out
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap().flatten() {
        let target = to.join(entry.file_name());
        if entry.path().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}

fn write_documents(dir: &Path, docs: &BTreeMap<String, String>) {
    let _ = std::fs::remove_dir_all(dir);
    for (relative, text) in docs {
        let path = dir.join(relative);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, text).unwrap();
    }
}

/// The first line where two files part ways, for a readable failure.
fn first_difference(expected: &str, actual: &str) -> String {
    for (i, (e, a)) in expected.lines().zip(actual.lines()).enumerate() {
        if e != a {
            return format!("line {}:\n  expected: {e}\n  actual:   {a}", i + 1);
        }
    }
    format!(
        "lengths differ ({} vs {} lines)",
        expected.lines().count(),
        actual.lines().count()
    )
}

fn compare(name: &str, expected: &BTreeMap<String, String>, actual: &BTreeMap<String, String>) {
    let mut problems = Vec::new();
    for path in expected.keys().chain(actual.keys()) {
        match (expected.get(path), actual.get(path)) {
            (Some(e), Some(a)) if e != a => {
                problems.push(format!("{path} changed, {}", first_difference(e, a)))
            }
            (Some(_), None) => problems.push(format!("{path} is no longer written")),
            (None, Some(_)) => problems.push(format!("{path} is new")),
            _ => {}
        }
    }
    problems.dedup();
    assert!(
        problems.is_empty(),
        "fixture {name}: saving changed the files. If that's deliberate, rerun with \
         BLOCKLOOM_BLESS=1.\n{}",
        problems.join("\n")
    );
}

#[test]
fn every_golden_project_saves_back_byte_for_byte() {
    blockloom_core::init();
    let mut names: Vec<_> = std::fs::read_dir(fixtures())
        .unwrap()
        .flatten()
        .filter(|e| e.path().is_dir())
        .map(|e| e.file_name().to_string_lossy().into_owned())
        .collect();
    names.sort();
    assert!(names.len() >= 4, "fixtures went missing: {names:?}");
    for name in names {
        let fixture = fixtures().join(&name);
        let input = fixture.join("input");
        let expected_dir = if fixture.join("expected").is_dir() {
            fixture.join("expected")
        } else {
            input.clone()
        };

        let work = scratch(&name);
        copy_dir(&input, &work);
        let opened =
            project::read_project_dir(&work).unwrap_or_else(|e| panic!("fixture {name}: {e}"));
        project::save_project(&opened, &work).unwrap();
        let saved = documents(&work);

        if blessing() {
            write_documents(&expected_dir, &saved);
        } else {
            compare(&name, &documents(&expected_dir), &saved);
        }

        // Saved output is a fixed point: reading it gives the same document
        // and saving that again writes the same bytes.
        let reopened = project::read_project_dir(&work).unwrap();
        assert_eq!(reopened, opened, "fixture {name}: reopening changed it");
        project::save_project(&reopened, &work).unwrap();
        compare(&format!("{name} (second save)"), &saved, &documents(&work));

        // Export is the same document as one file.
        let exported = work.join("export.blockloom-export");
        project::export_project(&opened, &exported).unwrap();
        let imported = project::read_project(&exported).unwrap();
        assert_eq!(
            imported.scenes.len(),
            opened.scenes.len(),
            "fixture {name}: export lost scenes"
        );
        for (a, b) in imported.scenes.iter().zip(&opened.scenes) {
            assert_eq!(a.actors, b.actors, "fixture {name}: export changed actors");
            assert_eq!(a.world, b.world, "fixture {name}: export changed the world");
        }

        let _ = std::fs::remove_dir_all(&work);
    }
}

// ─── Regenerating the inputs ───────────────────────────────────────────────

/// Every actor component with its defaults, made from its tag plus an empty
/// spec. Ones that need more than that are left out (and listed when
/// regenerating). `$player` names the first actor.
fn default_components(player: &str) -> (Vec<serde_json::Value>, Vec<String>) {
    use serde_json::json;
    let empty = || json!({});
    let specs: Vec<(&str, &str, serde_json::Value)> = vec![
        ("Render", "visible", json!(true)),
        ("Body", "physics", empty()),
        ("Rigidbody", "rigidbody", empty()),
        ("Collider", "collider", empty()),
        ("Constraint", "constraint", empty()),
        ("CharacterController", "controller", empty()),
        ("CharacterMotor", "motor", empty()),
        ("PlayerCamera", "player_camera", empty()),
        ("Joint", "joint", empty()),
        ("Brain", "brain", empty()),
        ("Camera", "camera", empty()),
        ("Script", "path", json!("assets/scripts/player.rs")),
        ("Parent", "parent", json!(player)),
        ("Custom", "name", json!("Health")),
        ("Material", "material", empty()),
        ("Fracture", "fracture", empty()),
        ("Emitter", "emitter", empty()),
        ("Trail", "trail", empty()),
        ("Light", "light", empty()),
        ("Light2d", "light2d", empty()),
        ("Conveyor", "conveyor", empty()),
        ("Hazard", "hazard", empty()),
        ("Animation", "animation", empty()),
        ("Volume", "volume", empty()),
        ("Probe", "probe", empty()),
        ("Terrain", "terrain", empty()),
        ("Sprite", "sprite", empty()),
        ("Water", "water", empty()),
        ("Buoyancy", "buoyancy", empty()),
        ("Parallax", "parallax", empty()),
        ("Room", "room", empty()),
        ("SoundZone", "zone", empty()),
    ];
    let mut tags: Vec<serde_json::Value> = specs
        .into_iter()
        .map(|(name, key, value)| json!({ "component": name, key: value }))
        .collect();
    tags.push(json!({ "component": "Persist" }));
    let mut made = Vec::new();
    let mut skipped = Vec::new();
    for tag in tags {
        match serde_json::from_value::<blockloom_core::components::ActorComponent>(tag.clone()) {
            Ok(component) => made.push(serde_json::to_value(component).unwrap()),
            Err(e) => skipped.push(format!("{}: {e}", tag["component"])),
        }
    }
    (made, skipped)
}

/// A project with one actor per component kind, two scenes, and the
/// editor-baseline canvases on the first actor.
fn kitchen(name: &str, mode: blockloom_core::scene::Mode) -> Project {
    use blockloom_core::components::ActorComponent;
    let mut project = Project::starter(name, mode);
    let player = project.actors[0].id.clone();
    let (components, skipped) = default_components(&player);
    if !skipped.is_empty() {
        eprintln!("{name}: left out\n  {}", skipped.join("\n  "));
    }
    for value in components {
        let component: ActorComponent = serde_json::from_value(value).unwrap();
        let label = component.name().to_string();
        let mut actor = project.actors[0].clone();
        actor.id = uuid::Uuid::new_v4().simple().to_string();
        actor.name = format!("With {label}");
        actor.components.insert(component);
        project.add_actor(actor);
    }
    let baseline = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../blockloom-app/tests/fixtures/editor-baseline/project");
    if let Ok(base) = project::read_project_dir(&baseline)
        && let Some(source) = base.actors.iter().find(|a| !a.graph.strands.is_empty())
    {
        project.actors[0].graph = source.graph.clone();
        project.globals = base.globals.clone();
        project.global_lists = base.global_lists.clone();
        project.global_dicts = base.global_dicts.clone();
    }
    project.add_scene("Level 2", None);
    project
}

#[test]
#[ignore = "rewrites the golden inputs; run by hand, then bless"]
fn regenerate_golden_inputs() {
    use blockloom_core::scene::Mode;
    blockloom_core::init();
    let root = fixtures();
    for (dir, mode) in [("kitchen-2d", Mode::TwoD), ("kitchen-3d", Mode::ThreeD)] {
        let input = root.join(dir).join("input");
        let _ = std::fs::remove_dir_all(&input);
        std::fs::create_dir_all(&input).unwrap();
        project::save_project(&kitchen(dir, mode), &input).unwrap();
        let _ = std::fs::remove_dir_all(input.join(".blockloom"));
    }

    // The pre-asset, pre-component shape: one embedded document whose actors
    // keep visual/placement/physics/visible flat and whose camera names the
    // followed actor.
    let legacy = root.join("legacy-embedded");
    let input = legacy.join("input");
    let _ = std::fs::remove_dir_all(&legacy);
    std::fs::create_dir_all(&input).unwrap();
    let project = Project::starter("Legacy", Mode::TwoD);
    let mut doc = serde_json::to_value(&project).unwrap();
    // Scenes carried no asset path before they were assets.
    for scene in doc["scenes"].as_array_mut().unwrap() {
        scene.as_object_mut().unwrap().remove("path");
    }
    let scene = &mut doc["scenes"][0];
    let follow = scene["actors"][0]["id"].clone();
    for actor in scene["actors"].as_array_mut().unwrap() {
        let components = actor["components"].as_array().cloned().unwrap_or_default();
        let field = |tag: &str, key: &str| {
            components
                .iter()
                .find(|c| c["component"] == tag)
                .map(|c| c[key].clone())
        };
        let flat = [
            ("visual", field("Look", "visual")),
            ("placement", field("Place", "placement")),
            ("physics", field("Body", "physics")),
        ];
        let object = actor.as_object_mut().unwrap();
        object.remove("components");
        for (key, value) in flat {
            if let Some(value) = value {
                object.insert(key.to_string(), value);
            }
        }
        object.insert("visible".into(), true.into());
    }
    scene["world"]["camera"]["follow"] = follow;
    std::fs::write(
        input.join("project.blockloom"),
        serde_json::to_string_pretty(&doc).unwrap(),
    )
    .unwrap();
    std::fs::create_dir_all(legacy.join("expected")).unwrap();
}

/// The derived schemas describe what serde really writes: every component
/// and world in every fixture passes its own schema.
#[test]
fn golden_documents_pass_their_derived_schemas() {
    use blockloom_plugin_api::schema::Schema;
    blockloom_core::init();
    let components = blockloom_core::components::ActorComponent::field_type();
    let world = blockloom_core::scene::World::field_type();
    for entry in std::fs::read_dir(fixtures()).unwrap().flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        let project = project::read_project_dir(&entry.path().join("input")).unwrap();
        for scene in &project.scenes {
            let errors = world.check_value(&serde_json::to_value(&scene.world).unwrap());
            assert!(errors.is_empty(), "{name}: world {errors:?}");
            for actor in &scene.actors {
                for component in actor.components.iter() {
                    let value = serde_json::to_value(component).unwrap();
                    let errors = components.check_value(&value);
                    assert!(errors.is_empty(), "{name}: {} {errors:?}", component.name());
                }
            }
        }
    }
}
